{
  "manifest_version": 3,
  "name": "Reel Archiver",
  "version": "1.0",
  "description": "Save the current reel/video link to my personal archive.",
  "action": {
    "default_title": "Save this video to my archive"
  },
  "background": {
    "scripts": ["background.js"]
  },
  "content_scripts": [
    {
      "matches": ["<all_urls>"],
      "js": ["content.js"]
    }
  ],
  "permissions": ["activeTab"],
  "host_permissions": ["http://localhost:8000/*"],
  "browser_specific_settings": {
    "gecko": {
      "id": "reel-archiver@yourdomain.com"
    }
  }
}
EOF

